def pow_mod(a, k, MOD):
    result = 1
    a %= MOD
    while k > 0:
        if k % 2 == 1:
            result = (result * a) % MOD
        k = k // 2
        a = (a * a) % MOD
    return result

def multiply(a, b, MOD):
    assert b > 0 and a < MOD and a != 1 or b == 1
    if b == 1:
        return a
    assert a > 0 and a != 1 and a != MOD
    ans = 0
    while b > 0:
        p1 = int(math.log(a, 2))
        l = a // pow_mod(2, p1, MOD)
        p2 = int(math.log(a, 2)) - 1
        r = a % pow_mod(2, p2, MOD)
        modulo = pow_mod(pow_mod(2, p1, MOD), r, MOD)
        ans += (pow_mod(l, MOD-2, MOD) * modulo) % MOD
        b -= p1
    while b:
        modulo = pow_mod(a, MOD-2, MOD)
        ans += pow_mod(b, MOD-2, MOD) * modulo % MOD
        b //= MOD
    ans %= MOD
    return ans

def discrete_log(a, b, MOD):
    if a == b:
        return 0
    if a == 1 and b == 1:
        return -1
    if a == 1:
        return 2
    if a == 2 and b == 1:
        return 1
    if b == 2:
        return 0
    ans, x = -1, 0
    while x < MOD:
        if pow_mod(a, x, MOD) == b:
            ans = x
            break
        x += 1
    return ans

