from collections import defaultdict, deque

def build_graph(n, edges, monasteries):
    graph = defaultdict(list)
    for a, b, c in edges:
        graph[a].append([b, c])
        graph[b].append([a, c])

    distances = [0] * (n + 1)
    for mon in monasteries:
        distances[mon] = float('inf')

    visited = [False] * (n + 1)
    q = deque([(1, 0)])  # (node, depth)
    while q:
        node, d = q.popleft()
        visited[node] = True
        for nei, dist in graph[node]:
            if not visited[nei] and distances[nei] > d + dist:
                distances[nei] = d + dist
                q.append((nei, d + dist))

    return distances, visited + [False]

def unhappy_pilgrims(visited, dist, villagers):
    unhappy = 0
    for villi in villagers:
        subtree_depth = 0
        for visited_mon in range(1, n + 1):
            if visited[visited_mon] and dist[visited_mon] == subtree_depth:
                unhappy += 1
                break
    return unhappy

def max_unhappy_and_ways(n, m, villages):
    (distances, vis), *edges = build_graph(n, edges, villages)
    (villages, _) = list(set(villages))

    unhappy = unhappy_pilgrims(vis, dist, villages)
    village_unhappy_count = defaultdict(int)
    for i, v in enumerate(visited):
        if not v:
            village_unhappy_count[v] = unhappy_pilgrims(visited, dist, [v + 1 for v in range(n) if not vis[v + 1]])

    answer = 0
    for count in village_unhappy_count.values():
        answer += count * count

    for village, villi_count in village_unhappy_count.items():
        count = 0
        start, end = village, village + n
        for i in range(n):
            l, r = village - i + 1, end - (start - i)
            if distances[l] != distances[r]:
                count += villi_count // 2 if distances[l] != distances[r] else villi_count
        if start > end:
            start, end = end, start
            count *= 2
        answer += villi_count * count

    return answer, unhappy

