from collections import defaultdict

def max_pots_sum(graph):
    rows, cols = defaultdict(list), defaultdict(int)
    for i, j in graph:
        rows[i].append(-j-1)
        rows[j].append(-i-1)
        cols[i].append(j)
        cols[j].append(i)

    for r in rows:
        rows[r].sort()

    max_pots = 0
    for r in range(len(rows)):
        cur = [0 for _ in range(len(cols))]
        state = [-1 for _ in range(len(rows[r]))]
        cur[r] = len(rows[r])

        while True:
            stack = []
            cur[r].sort()
            for i in range(len(rows[r])):
                if state[i] == -1 and rows[r][i] not in stack:
                    queue = [rows[r][i]]
                else: # any of the completed paths in queue finish on nodes present on stack
                    while queue and queue[-1] in stack:
                        queued = []
                        queue, queued, node = stack[-1], deque(queue), queue[-1]
                        for in_idx in rows[node]:
                            ind_cur = cur[in_idx].pop() if node in cur and in_idx not in cur[node] else cur[r].pop()
                            if in_idx == -1 or len(cur[in_idx]) < ind_cur:
                                queue.append(in_idx)

                        state[queued[-1]] = 1
                        max_pots, stack = max_pots + cur[r].pop(), sorted(stack)

            if not stack:
                break

    return max_pots + sum([len(rows[r]) for r in cols if len(rows[r]) > 0])

