from collections import deque

def min_cost_to_avoid_set_or_kill(n, s, program):
    cost = 0
    set_deque = deque([False] * n)
    i = -2
    for line in program:
        if line == 'set':
            y, v = map(int, input().split()) if set_deque[i+1] else (0, int(input()))
            if i + 1 != 0 and y == s:
                return min(cost + v, (cost + sum(set_deque) + 1) * (n - i -1))
            elif i + 1 < 0:
                set_deque[i + 1] = True
            cost += v
        elif line == 'if':
            set_deque[i + 1] = True
        elif line == 'end':
            set_deque.pop()
        i += 1
    return cost

