    def shortest_path(start, goal, costs, visited):
        pq = [(start, 0)]
        while pq:
            node, cost = pq.pop(0)
            if node == goal:
                return cost, visited[node]
            visited[node] = True
            for neighbor, weight in graph[node]:
                if not visited[neighbor]:
                    pq.append((neighbor, weight + cost))
        return float('inf')

    shortest_distances = {}
    for start in range(n):
        shortest_distance = shortest_path(start, -1, {}, [False] * n)
        if shortest_distance != float('inf'):
