from collections import defaultdict
from math import inf

def find_path_lengths(roads):
    n = len(roads)
    lengths = defaultdict(lambda: inf)
    parents = [i for i in range(n)]
    rnk = [0 for _ in range(n)]

    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]

    def union(x, y):
        rnk_x = rnk[find(x)]
        rnk_y = rnk[find(y)]
        if rnk_x < rnk_y:
            parents[find(x)] = find(y)
        elif rnk_x > rnk_y:
            parents[find(y)] = find(x)
        else:
            parents[find(y)] = find(x)
            rnk[find(x)] += 1

    def path_lengths():
        for edge in roads:
            union(edge[0] - 1, edge[1] - 1)
        for i in range(n):
            for j in range(i + 1, n):
                height = rnk[find(i)]
                if height == rnk[find(j)]:
                    yield lengths[find(i)], lengths[find(j)]

    return list(path_lengths())

def main():
    n, m = map(int, input().split())
    roads = [[int(x) - 1 for x in input().split()] for _ in range(m)]
    print(*[sum(1 for v in (path_lengths() if i < j else [])]) for i, j in zip([0] + [n] * (n - 1), list(range(1, n)) + [n]))

