    dist_to_this_town = defaultdict(lambda: float('inf'))
    q = deque([monasteries[0]])
    dist_to_this_town[monasteries[0]] = 0
    while q:
        node = q.popleft()
        i = 0
        for nei, length in graph[node]:
            if dist_to_this_town[nei] > dist_to_this_town[node] + length:
                dist_to_this_town[nei] = dist_to_this_town[node] + length
                q.append(nei)

    # Initialize maximum unhappy pilgrims and ways
    max_unhappy = 0
    ways = 0

    # Iterate over each possible town to destroy
    for i in range(1, n):
        dist_to_farthest = 0
        jiedui = False

        # Find the farthest monastic town from this town
        for mon in monasteries[1:]:
            if dist_to_this_town[mon] > dist_to_farthest:
                dist_to_farthest = dist_to_this_town[mon]

        # If the farthest monastic town cannot be reached from this town, update max_unhappy pilgrims
        if dist_to_farthest - 1 < 0:
            continue
        jiedui = True
        for mon in monasteries[1:]:
            if dist_to_this_town[mon] > dist_to_farthest:
                dist_to_farthest = dist_to_this_town[mon]

        # Calculate ways to make this plan work
        for mon in monasteries:
            other_monasters = [x for x in monasteries if x != mon]
            has_shortest_path = 0
            dis = float('inf')
            for mon in other_monasters:
                for nei, length in graph[mon]:
                    if dist_to_this_town[mon] + length > dist_to_this_town[nei]:
                        if dist_to_this_town[nei] - 1 < dis:
                            dis = dist_to_this_town[nei] - 1
            if dis > 0:
                has_shortest_path += 1
            max_unhappy += has_shortest_path / len(other_monasters)
            if jiedui:
                ways += dist_to_farthest * (has_shortest_path + 1) // len(other_monasters)
                if has_shortest_path + 1 == len(other_monasters) and dis > 1:
                    max_unhappy += 1
    return int(max_unhappy), int(ways)
