            max_points = max(max_points, sum(pi_values[word] * carryover[word] for word in carryover))
        for i in range(position, len(crossword)):
            if i not in seen_positions and crossword[i] in word_counts and word_counts[crossword[i]] > 0:
                seen_positions.add(i)
                if i < len(crossword) - 1 and crossword[i + 1] in word_counts:
                    dfs(carryover.copy(), i + 1)
                else:
                    dfs({}, i + 1)
                seen_positions.remove(i)

    dfs({}, 0)
    return max(max_points, sum(pi * calc_val(crossword[i:i+k], word_counts) for (i, word) in enumerate(words, 1) for calc_val in [count, count * word_counts[word]] if i + word.count(word[0]) <= k for k in range(1, x + 1)))

def count(word, crossword):
    return sum([1 if crossword[i] == word[j] else 0 for i, j in enumerate(word)])

def count_full(word, crossword):
    full_count = 0
    for i in range(len(crossword) - len(word) + 1):
        if crossword[i:i+len(word)].startswith(word):
            full_count += 1
    return full_count
