def find_array(a: str, b: str, c: str) -> str:
    n = int(a[1:])
    b = list(map(int, list(a[1:-1].split())))
    c = list(map(int, list(a[1:-1].split())))

    if n != len(b) or n != len(c):
        return "-1"

    result = [''] * n
    for i in range(n):
        b = bin(b[i])[2:].zfill(32)
        c = bin(c[i])[2:].zfill(32)

        carry = 0
        for j in range(32):
            digit = (int(b[j]) & int(c[j])) ^ int(carry)
            carry = int(b[j]) | int(c[j])

            if digit != -1:
                if j == 0:
                    carry_bits = format(digit, 'b')
                else:
                    carry_bits = f'{carry_bits}.{digit}'
            else:
                carry_bits = carry_bits.replace('.', '')

        if not carry_bits or carry_bits[0] != '0':
            return "-1"

        if j != 31:
            result[i] = carry_bits[:-1]

    return " ".join(result)

