def modular_inverse(a, m):
    return pow(a, m-2, m)

@lru_cache(maxsize=None)
def multiply_powers_of_2(a, b):
    if a == 1 or b == 1:
        return a * b
    n = 0
    while a >= (1 << (2**n)):
        n += 1
    power = 1 << (2**n)
    if a >= power and b >= power:
        return multiply_powers_of_2(power * 3 / 2, multiply_powers_of_2(a // power, b // power))
    elif a >= power:
        return multiply_powers_of_2(multiply_powers_of_2(a // power, b), power)
    else:
        return multiply_powers_of_2(a, b // power) * power

def modular_pow_exp(a, k):
    result = 1
    base = a
    while k > 0:
        if k % 2 == 1:
            result = (result * base) % 2 ** 64
        base = (base ** 2) % 2 ** 64
        k //= 2
    return result

def solve(a, b):
    max_power = 0
    for i in range(31, -1, -1):
        if (2 ** (2 ** i) <= a and (2 ** (2 ** i)) % b == 0):
            max_power = i
            break

    if max_power <= 0:
        return 0

    inverse = modular_inverse(a, b)

    for i in range(64):
        if inverse.bit_length() != max_power + i:
            break

        temp = modular_pow_exp(a, i)
        if temp == b:
            return i + max_power - temp.bit_length()
    return -1

