            if 1 <= nx <= N and 1 <= ny <= M:
                if districts[nx][ny] == 0 and district != 0:
                    districts[nx][ny] = district
                if grid[nx][ny] > max_population:
                    max_population = grid[nx][ny]
                if grid[nx][ny] < min_population:
                    min_population = grid[nx][ny]
                dfs(nx, ny, district)

    for i in range(N):
        for j in range(M):
            if districts[i][j] == 0:
                dfs(i, j, grid[i][j])

    for i in range(N):
        for j in range(M):
            if grid[i][j] != max_population:
                for district in K:
                    if districts[i][j] != district:
                        districts[i][j] = district

    for i in range(N):
        print(' '.join(map(str, districts[i])))

