from heapq import heappush, heappop
from collections import defaultdict
from math import inf

def dijkstra(graph, start, end=None):
    if not graph:
        return 0
    n = len(graph)
    distances = [inf] * n
    distances[start] = 0
    heap = [(0, start)]
    for distance, node in heap:
        for neighbor, weight in graph[node].items():
            distance_to_neigh = distance + weight
            if distance_to_neigh < distances[neighbor]:
                distances[neighbor] = distance_to_neigh
                heappush(heap, (distance_to_neigh, neighbor))
    if end is not None:
        return distances[end] if distances[end] != inf else -1
    else:
        return sum(distances)

def solve(n, m, roads):
    graph = defaultdict(dict)
    num_relations = [0] * n
    for road in roads:
        city1, city2, length = road
        graph[city1][city2] = length
        graph[city2][city1] = length
        num_relations[city1] += 1
        num_relations[city2] += 1

    result = [0] * (n - 1)
    for _ in range(n - 1):
        if num_relations[0] == n - 1:
            longest_path_distance = dijkstra(graph, 0)
            for i in range(1, n):
                result[i - 1] += lengths[i] * longest_path_distance
            break
        else:
            continue

    return result

