def findMinimumBurlesToAvoidMismatch(commands):
    dp = [0, 1]  # dp[i] stores the minimum burles spent to handle the first i-1 commands
    pre = []

    for i in range(len(commands)):
        bp = dp[1]
        if commands[i][0] == "if" and pre:
            if int(commands[i][2]) >= int(commands[pre[-1]][2]):
                dp[1] = min(dp[1], pre[-1] + 1)  # Spend a burle on the current if and the last unmatched end
            if int(commands[i][2]) > int(commands[pre[-1]][2]):
                dp[1] = min(dp[1], dp[0])  # No need to spend 1 if the current is matched with the last
        else:
            dp[0] = min(pre[-1] + 1, dp[0])  # Spend a burle on the current if the current doesn't match the last end

        pre.append(commands[i])

    return min(dp)

