from collections import defaultdict, deque
from math import inf

def bfs(graph, start):
    distances = {}
    distances[start] = 0
    queue = deque([start])

    while queue:
        current = queue.popleft()
        if current in distances:
            continue
        for neighbor, weight in graph[current].items():
            if neighbor not in distances:
                distances[neighbor] = distances[current] + weight
                queue.append(neighbor)

    return distances

def max_unhappy_pilgrims(graph, monasteries):
    num_unhappy_pilgrims = max(distinct_options(graph, monast, monast+dist, 1) for monast in monasteries)

    possible_towns = len(graph)

    return num_unhappy_pilgrims, possible_towns

def distinct_options(graph, start, end, count):
    options = 1
    queue = deque([(start, count)])
    visited = set([start])

    while queue:
        current, count = queue.popleft()
        if current == end:
            options += 1
        for neighbor, weight in graph[current].items():
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, count+weight))

    options -= 1

    return count if start != end or count > 0 else options

