from collections import defaultdict

def find_array(b, c):
    n = len(b)
    # Convert binary strings to integers
    count = defaultdict(int)
    for num in b:
        count[''.join(map(str, num)) % 2] += 1
    for num in c:
        count[''.join(map(str, num))] += 2

    for i in range(n - 1):
        if count['0' * (n - i - 1) + '1' * i + '0'] > count['0' * (n - i - 1) + '0' * (i + 1)]:
            return -1
        elif count['0' * (n - i - 1) + '1' * i + '0'] == count['0' * (n - i - 1) + '0' * (i + 1) + '0']:
            return -1

    result = [0] * n
    for d in range(2 ** n):
        if '{0:0{n}b}'.format(d)[::-1][0] == '1':
            bit = {'0': 0, '1': 1}
            temp = 0
            for i in range(n):
                if bit['1' * i + '0' * (n - i)] in count:
                    temp |= 1 << (n - i)
            if temp in count:
                js_result = '00' + count[temp]
                result[::2] = list(map(int, js_result.replace('1', '1').replace('0', '0')))
                return ''.join(map(str, result))
    return '-1'

