def count_non_decreasing_sequence_length(string):
    stack = [0]
    for i, digit in enumerate(string):
        while len(stack) > 1 and digit >= string[stack[-1]]:
            idx = stack.pop()
            string = string[:idx] + [string[idx - len(string):idx].count(digit)] + string[idx+1:]
        stack.append(i + 1)
    return len(stack) - 1

