import sys

def process_string(string, queries):
    switches = []
    results = []

    def switch_digits(start, end):
        nonlocal string
        for i in range(start, end+1):
            if string[i] == '4':
                string = string[:i] + '7' + string[i+1:]
            elif string[i] == '7':
                string = string[:i] + '4' + string[i+1:]

    for query in queries:
        if query[0] == 'switch':
            l, r = map(int, query[1].split())
            switches.append((l, r))
        else:
            switch_digits(switches[-1][0], switches[-1][1])
            results.append(len(max(find_subsequence(switches[-1][0], switches[-1][1]))))

    return results

def find_subsequence(start, end):
    if not subsequence(start, end):
        return []
    return find_longest_common_subsequence(start, end)

def subsequence(start, end):
    i, j = start, 0
    while i <= j <= end:
        if i == start:
            if string[i][j] == '4':
                j += 1
            else:
                return False
        elif j == end:
            if string[i][j] == '7':
                j += 1
            else:
                return False
        elif string[i][j] == '4':
            if j == 0:
                j += 1
            elif string[i][j-1] == '7':
                j += 1
            else:
                return False
        else:
            if j == 0:
                i += 1
            elif string[i][j-1] == '4':
                j += 1
            else:
                return False
    return True

def find_longest_common_subsequence(start, end):
    prefix_sum = {}
    for i in range(end - start + 1):
        if string[start][i] not in prefix_sum:
            prefix_sum[string[start][i]] = {}
        for char in prefix_sum[string[start][i]]:
            same_char_count = i - (prefix_sum[string[start][i]][char] - 1)
            if same_char_count in prefix_sum[string[start][i]][char]:
                common_length = i - prefix_sum[string[start][i]][char] + (
                    common_length := (max(common_length, end - prefix_sum[string[start][i]][char]))
                )
            prefix_sum[string[start][i]][char] = same_char_count + 1
    i = j = 0
    largest_length = 0
    while start + i <= end:
        same_char_count = i - (prefix_sum[string[start][i]][string[start][j]] - 1)
        largest_length = max(largest_length, i - j + same_char_count)
        if largest_length == end - start + 1:
            break
        if j == len(string[start])-1:
            i += 1
        elif string[start][j+1] == string[start][i]:
            j += 1
        else:
            i += 1
            j = i
    return prefix_sum, largest_length

