                return (princess_x + shadow_x) % 2 == 1
        return (princess_x + shadow_x) % 2 == 0
    return False

def find_path(princess_x, princess_y, shadow_x, shadow_y):
    queue = deque([(princess_x, princess_y, 0)])
    labyrinth = [[float('inf')] * 101 for _ in range(101)]
    last_turns = {cell: float('inf') for cell in product(range(101), range(101))}
    last_turns[(princess_x, princess_y)] = 0

