            if 0 <= new_x < 101 and 0 <= new_y < 101 and labyrinth[new_x][new_y] >= last_turns[current_x, current_y] + 1 and (dead_end := can_catch_shadow(new_x, new_y, shadow_x, shadow_y, set()) or prev_turns.get((new_x, new_y), float('inf')) < prev_turns[(current_x, current_y)]):
                queue.append((new_x, new_y, last_turns[current_x, current_y] + 1))
                last_turns[new_x, new_y] = prev_turns[(current_x, current_y)] + 1
        labyrinth[current_x][current_y] = prev_turns[(current_x, current_y)]
        last_turns[current_x, current_y] = prev_turns[(current_x, current_y)] + 1

