from collections import deque

def move_left(r, c):
    return r, c - 1

def move_right(r, c):
    return r, c + 1

def move_up(r, c):
    return r - 1, c

def move_down(r, c):
    return r + 1, c

def catch_shadow(vx, vy, sx, sy, trees):
    q = deque([(vy, sx)])
    seen = {(vy, sx)}

    while q:
        r, c = q.popleft()
        if (r, c) == (vy, vx):
            return ''.join('D'*(vy == vy-y)+('U'*(vy != vy-y)) + 'L'*(x == vx-x) + ('R'*(vx != rx-x)) for x in range(vx, c) if (c, x) not in trees and (c, x) not in seen)
        seen.add((r, c))
        for dr, dc in [(0, -(r-sx)), (0, r-sy), (-(c-vx), 0), (c-vx, 0)]:
            if dr > -1 and dr <= 1 and dc > -1 and dc <= 1 and (dr, dc) not in trees and (dr, dc) not in seen:
                q.append((dr, dc))

    return "-1"

